<div class="grid grid-cols-1 md:grid-cols-2 gap-5">
    <div><label for="code" class="admin-label">Coupon Code *</label><input id="code" name="code" value="{{ old('code', $coupon->code) }}" required maxlength="40" class="paper-input admin-input uppercase"><p class="admin-help">Letters, numbers, underscores and hyphens only.</p></div>
    <div><label for="discount_type" class="admin-label">Discount Type *</label><select id="discount_type" name="discount_type" class="paper-input admin-input"><option value="percentage" @selected(old('discount_type', $coupon->discount_type) === 'percentage')>Percentage</option><option value="fixed" @selected(old('discount_type', $coupon->discount_type) === 'fixed')>Fixed amount</option></select></div>
    <div><label for="discount_value" class="admin-label">Discount Value *</label><input id="discount_value" name="discount_value" type="number" min="0.01" step="0.01" value="{{ old('discount_value', $coupon->discount_value) }}" required class="paper-input admin-input"></div>
    <div><label for="minimum_order_amount" class="admin-label">Minimum Order Amount *</label><input id="minimum_order_amount" name="minimum_order_amount" type="number" min="0" step="0.01" value="{{ old('minimum_order_amount', $coupon->minimum_order_amount ?? 0) }}" required class="paper-input admin-input"></div>
    <div><label for="usage_limit" class="admin-label">Usage Limit</label><input id="usage_limit" name="usage_limit" type="number" min="1" step="1" value="{{ old('usage_limit', $coupon->usage_limit) }}" placeholder="Unlimited" class="paper-input admin-input"></div>
    <div class="hidden md:block"></div>
    <div><label for="starts_at" class="admin-label">Start Date &amp; Time</label><input id="starts_at" name="starts_at" type="datetime-local" value="{{ old('starts_at', $coupon->starts_at?->format('Y-m-d\TH:i')) }}" class="paper-input admin-input"></div>
    <div><label for="expires_at" class="admin-label">Expiry Date &amp; Time</label><input id="expires_at" name="expires_at" type="datetime-local" value="{{ old('expires_at', $coupon->expires_at?->format('Y-m-d\TH:i')) }}" class="paper-input admin-input"></div>
    <label class="md:col-span-2 flex items-center gap-2 text-sm font-semibold text-gray-700"><input type="checkbox" name="is_active" value="1" @checked(old('is_active', $coupon->is_active)) class="accent-brandRed w-4 h-4"><span>Coupon is active</span></label>
</div>
